<script lang="ts">
  import Icon from './Icon.svelte';
  let { english = false }: { english?: boolean } = $props();
  let currentId = $state('wedding'), tab = $state<'details' | 'calendar' | 'messages'>('details');
  let statuses = $state<Record<string, 'inquiry' | 'confirmed'>>({ wedding:'inquiry', business:'confirmed', party:'inquiry' });
  let counts = $state<Record<string, number>>({ wedding:96, business:48, party:60 });
  let reply = $state(''), replies = $state<Record<string,string[]>>({ wedding:[],business:[],party:[] });
  let module: HTMLDivElement;
  const events = $derived([
    {id:'wedding',name:english ? 'Wedding reception' : 'Svadobná hostina',day:14,time:'14:00 - 23:00',short:english ? 'Wedding' : 'Svadba'},
    {id:'business',name:english ? 'Team gathering' : 'Firemné stretnutie',day:7,time:'09:00 - 17:00',short:english ? 'Company' : 'Firma'},
    {id:'party',name:english ? 'Birthday celebration' : 'Narodeninová oslava',day:21,time:'17:00 - 23:00',short:english ? 'Birthday' : 'Oslava'},
  ]);
  const current = $derived(events.find(event => event.id === currentId)!);
  export function openInquiry() {
    currentId = 'wedding'; tab = 'details';
    module.scrollIntoView({ block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' });
  }
  function send(event: SubmitEvent) { event.preventDefault(); if (reply.trim()) { replies[currentId] = [...replies[currentId], reply.trim()]; reply = ''; } }
</script>
<div class="booking-workflow" id="workspace" bind:this={module}>
  <div class="workflow-header"><div><img src="/Hallify.svg" alt="" width="24" height="24"><span>{english ? 'Riverside studio' : 'Ateliér pri rieke'}</span></div><span class="workflow-demo-label">{english ? 'Interactive demo' : 'Interaktívna ukážka'}</span></div>
  <div class="workflow-body">
    <aside class="workflow-inbox" aria-label={english ? 'Sample inquiries' : 'Ukážkové dopyty'}><p>{english ? 'Inquiries & bookings' : 'Dopyty a rezervácie'}</p>{#each events as event}<button class:active={currentId === event.id} aria-pressed={currentId === event.id} onclick={() => { currentId = event.id; reply = ''; }}><small>{event.day}. 11. 2026</small><strong>{event.name}</strong><span>{counts[event.id]} {english ? 'guests' : 'hostí'}</span><em class:confirmed={statuses[event.id] === 'confirmed'}>{statuses[event.id] === 'confirmed' ? (english ? 'Confirmed' : 'Potvrdené') : (english ? 'New inquiry' : 'Nový dopyt')}</em></button>{/each}</aside>
    <div class="workflow-detail"><div class="workflow-detail-heading"><p>{current.short}</p><h2>{current.name}</h2><span>{current.day}. 11. 2026 · {current.time}</span></div><div class="workflow-tabs" role="group" aria-label={english ? 'Booking workspace' : 'Pracovný priestor rezervácie'}>{#each ['details','calendar','messages'] as id}<button aria-pressed={tab === id} onclick={() => tab = id as typeof tab}>{id === 'details' ? (english ? 'Details' : 'Prehľad') : id === 'calendar' ? (english ? 'Calendar' : 'Kalendár') : (english ? 'Messages' : 'Správy')}</button>{/each}</div>
      {#if tab === 'details'}<div class="workflow-overview"><div class="workflow-facts"><label>{english ? 'Guest count' : 'Počet hostí'}<input type="number" min="1" max="120" bind:value={counts[currentId]} aria-label={english ? 'Sample guest count' : 'Ukážkový počet hostí'}></label><div><small>{english ? 'Venue' : 'Priestor'}</small><strong>{english ? 'Main hall' : 'Hlavná sála'}</strong></div><div><small>{english ? 'Layout' : 'Usporiadanie'}</small><strong>{currentId === 'business' ? (english ? 'Conference' : 'Konferencia') : (english ? 'Banquet' : 'Banket')}</strong></div><div><small>{english ? 'Add-ons' : 'Doplnky'}</small><strong>{currentId === 'business' ? (english ? 'AV & refreshments' : 'Technika a občerstvenie') : 'Catering'}</strong></div></div><div class="workflow-request"><span aria-hidden="true"><Icon name="mail" /></span><p>{currentId === 'business' ? (english ? 'We need a projector and coffee for a full-day team meeting.' : 'Na celodenné firemné stretnutie potrebujeme projektor a kávu.') : (english ? 'Could we arrange the tables and discuss catering for our guests?' : 'Mohli by sme dohodnúť rozloženie stolov a catering pre našich hostí?')}</p></div><button class="workflow-confirm" class:confirmed={statuses[currentId] === 'confirmed'} disabled={statuses[currentId] === 'confirmed' || !counts[currentId] || counts[currentId] > 120 || counts[currentId] < 1} onclick={() => statuses[currentId] = 'confirmed'}>{statuses[currentId] === 'confirmed' ? (english ? 'Confirmed in demo ✓' : 'Potvrdené v ukážke ✓') : (english ? 'Confirm sample inquiry' : 'Potvrdiť ukážkový dopyt')} <Icon /></button>{#if statuses[currentId] === 'confirmed'}<button class="workflow-undo" onclick={() => statuses[currentId] = 'inquiry'}>{english ? 'Reset to inquiry' : 'Vrátiť na dopyt'}</button>{/if}</div>
      {:else if tab === 'calendar'}<div class="workflow-calendar"><h3>November 2026</h3><div class="workflow-calendar-week">{#each english ? ['Mo','Tu','We','Th','Fr','Sa','Su'] : ['Po','Ut','St','Št','Pi','So','Ne'] as day}<span>{day}</span>{/each}</div><div class="workflow-calendar-days">{#each Array(6) as _}<span></span>{/each}{#each Array(30) as _, i}{@const event = events.find(e => e.day === i + 1)}<button disabled={!event} class:event-day={!!event} aria-pressed={current.day === i + 1} aria-label={`${i + 1}. november 2026${event ? ', ' + event.name : ''}`} onclick={() => { if (event) currentId = event.id; }}>{i + 1}</button>{/each}</div><p>{english ? 'Choose a highlighted day to see its event.' : 'Vyberte zvýraznený deň a pozrite jeho podujatie.'}</p></div>
      {:else}<div class="workflow-messages"><p class="workflow-message client">{english ? 'Thank you. Can we confirm the guest count and the room setup?' : 'Ďakujeme. Môžeme si potvrdiť počet hostí a usporiadanie sály?'}</p>{#each replies[currentId] as message}<p class="workflow-message team">{message}</p>{/each}<form onsubmit={send}><label class="sr-only" for="workflow-reply">{english ? 'Sample reply' : 'Ukážková odpoveď'}</label><input id="workflow-reply" bind:value={reply} maxlength="500" placeholder={english ? 'Try writing a reply…' : 'Skúste napísať odpoveď…'}><button type="submit" disabled={!reply.trim()} aria-label={english ? 'Add a reply to the demo' : 'Pridať odpoveď do ukážky'}><Icon name="send" /></button></form><p class="workflow-local-note">{english ? 'Replies stay in this demo.' : 'Odpovede zostávajú len v tejto ukážke.'}</p></div>{/if}
    </div>
  </div>
  <div class="workflow-footer"><span>{english ? 'From inquiry to a prepared event.' : 'Od dopytu po pripravenú akciu.'}</span><span>{english ? 'Try the tabs and confirm an inquiry.' : 'Skúste záložky a potvrďte dopyt.'}</span></div>
</div>
